268	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
269		sort.SliceStable(checkpoints, func(i, j int) bool {
270			left := checkpoints[i].CreatedAt
271			right := checkpoints[j].CreatedAt
272			switch {
273			case left.IsZero() && right.IsZero():
274				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
275			case left.IsZero():
276				return false
277			case right.IsZero():
278				return true
279			case left.Equal(right):
280				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
281			default:
282				return left.Before(right)
283			}
284		})
285	}
