// every session's compact transcript and /full/<n> artifacts in place. When
// true, the per-checkpoint repair path is a guaranteed no-op and can be
// skipped. Any uncertainty (missing v1 session count, artifact lookup error)
// returns false so the caller falls back to the full repair path.
func v2CheckpointFullyMigrated(v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, existing *checkpoint.CheckpointSummary) bool {
	if existing == nil || info.SessionCount == 0 || info.SessionCount != len(existing.Sessions) {
		return false
	}
	for i, session := range existing.Sessions {
		if session.Transcript == "" {
			return false
		}
		ok, err := hasFullSessionArtifacts(v2Store, info.CheckpointID, i)
		if err != nil || !ok {
			return false
		}
	}
	return true
}

