12	// spinnerFrames matches the bubbles/spinner Dot frames used by the activity
13	// TUI, so a CLI spinner here visually matches `entire activity`.
14	var spinnerFrames = []string{"⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯", "⣷"}
15	
16	const (
17		spinnerInterval = 100 * time.Millisecond
18		// spinnerInitialDelay is how long an operation must run before the
19		// spinner appears at all. Faster operations don't get a spinner —
20		// avoids flicker on warm runs that complete in under a quarter second.
21		spinnerInitialDelay = 250 * time.Millisecond
22	)
23	
24	// startSpinner prints msg followed by an animated spinner to w when the
25	// operation takes longer than spinnerInitialDelay. Returns a stop function
26	// that clears the spinner line and prints suffix (with a newline) if
27	// non-empty. Fast operations that call stop before the initial delay
28	// elapses produce no output at all.
29	//
30	// When w is not a terminal (CI, redirected output, agent subprocess), the
31	// spinner and the suppression message are both omitted — non-interactive
32	// callers get clean output without progress chatter.
33	func startSpinner(w io.Writer, msg string) func(suffix string) {
34		if !interactive.IsTerminalWriter(w) {
35			return func(suffix string) {
36				if suffix != "" {
37					fmt.Fprintln(w, suffix)
38				}
39			}
40		}
41	
42		done := make(chan struct{})
43		stopped := make(chan struct{})
44		go func() {
45			defer close(stopped)
46			select {
47			case <-done:
48				return // operation finished before the spinner would appear
49			case <-time.After(spinnerInitialDelay):
50			}
51			ticker := time.NewTicker(spinnerInterval)
52			defer ticker.Stop()
53			frame := 0
54			fmt.Fprintf(w, "\r%s %s", spinnerFrames[frame], msg)
55			frame = (frame + 1) % len(spinnerFrames)
56			for {
57				select {
58				case <-done:
59					return
60				case <-ticker.C:
61					fmt.Fprintf(w, "\r%s %s", spinnerFrames[frame], msg)
62					frame = (frame + 1) % len(spinnerFrames)
63				}
64			}
65		}()
66		return func(suffix string) {
67			close(done)
68			<-stopped
69			// \r\033[K is a no-op on a line that was never drawn; on a drawn
70			// line it returns the cursor and clears it.
71			fmt.Fprint(w, "\r\033[K")
72			if suffix != "" {
73				fmt.Fprintln(w, suffix)
74			}
75		}
76	}
