78	type progressBar struct {
79		w       io.Writer
80		label   string
81		total   int
82		current int
83		width   int
84		enabled bool
85	}
86	
87	func startProgressBar(w io.Writer, label string, total int) *progressBar {
88		p := &progressBar{
89			w:       w,
90			label:   label,
91			total:   total,
92			width:   24,
93			enabled: total > 0 && interactive.IsTerminalWriter(w),
94		}
95		if !p.enabled {
96			return p
97		}
98	
99		counter := fmt.Sprintf(" %d/%d (100%%)", total, total)
100		available := getTerminalWidth(w) - len(label) - len(counter) - len(" []")
101		p.width = min(max(available, 10), 32)
102		p.render()
103		return p
104	}
105	
106	func (p *progressBar) Increment() {
107		p.current++
108		if p.current > p.total {
109			p.current = p.total
110		}
111		p.render()
112	}
113	
114	func (p *progressBar) Finish() {
115		if !p.enabled {
116			return
117		}
118		fmt.Fprint(p.w, "\r\033[K")
119	}
120	
121	func (p *progressBar) render() {
122		if !p.enabled {
123			return
124		}
125	
126		filled := 0
127		percent := 0
128		if p.total > 0 {
129			filled = p.current * p.width / p.total
130			percent = p.current * 100 / p.total
131		}
132		if p.current >= p.total {
133			filled = p.width
134			percent = 100
135		}
136	
137		bar := strings.Repeat("#", filled) + strings.Repeat("-", p.width-filled)
138		fmt.Fprintf(p.w, "\r%s [%s] %d/%d (%d%%)", p.label, bar, p.current, p.total, percent)
139	}
