116		parsed := make(map[plumbing.ReferenceName]v2RefPushResult, len(refs))
117		for _, line := range strings.Split(output, "\n") {
118			result, ok := parsePushRefStatusLine(line)
119			if ok {
120				parsed[result.refName] = result
121			}
122		}
123	
124		var fallbackErr error
125		if pushErr != nil {
126			fallbackErr = classifyPushFailure(ctx, output, pushErr)
127			if len(parsed) > 0 && len(parsed) < len(refs) {
128				logging.Debug(ctx, "push-v2: incomplete push porcelain output",
129					slog.Int("parsed_refs", len(parsed)),
130					slog.Int("expected_refs", len(refs)),
131					slog.String("error", pushErr.Error()),
132					slog.String("output", output),
133				)
134			}
135		}
136	
137		results := make([]v2RefPushResult, 0, len(refs))
138		for _, refName := range refs {
139			if result, ok := parsed[refName]; ok {
140				results = append(results, result)
141				continue
142			}
143			if pushErr != nil && len(parsed) > 0 {
144				results = append(results, v2RefPushResult{
145					refName: refName,
146					err:     fmt.Errorf("status missing for %s", shortRefName(refName)),
147				})
148				continue
149			}
150			err := fallbackErr
151			if err != nil {
152				err = fmt.Errorf("failed to push %s: %w", shortRefName(refName), err)
153			}
154			results = append(results, v2RefPushResult{
155				refName: refName,
156				err:     err,
157			})
158		}
159		return results
160	}
