162	func parsePushRefStatusLine(line string) (v2RefPushResult, bool) {
163		fields := strings.Split(line, "\t")
164		if len(fields) < 2 || fields[0] == "" {
165			return v2RefPushResult{}, false
166		}
167	
168		refName, ok := pushStatusRef(fields[1])
169		if !ok {
170			return v2RefPushResult{}, false
171		}
172	
173		switch fields[0][0] {
174		case '!':
175			err := classifyPushOutput(strings.Join(fields[2:], "\t"))
176			return v2RefPushResult{
177				refName: refName,
178				err:     fmt.Errorf("failed to push %s: %w", shortRefName(refName), err),
179			}, true
180		case '=':
181			return v2RefPushResult{
182				refName: refName,
183				result:  pushResult{upToDate: true},
184			}, true
185		default:
186			return v2RefPushResult{refName: refName}, true
187		}
188	}
