190	func pushStatusRef(statusRef string) (plumbing.ReferenceName, bool) {
191		_, dst, ok := strings.Cut(statusRef, ":")
192		if !ok || dst == "" {
193			return "", false
194		}
195		return plumbing.ReferenceName(dst), true
196	}
