198	// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
199	// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
200	//
201	// For /full/current: if the remote has archived generations not present locally,
202	// another machine rotated. In that case, local data is merged into the latest
203	// archived generation instead of into /full/current (see handleRotationConflict).
204	func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
205		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
206		defer cancel()
207	
208		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
209		if err != nil {
210			return fmt.Errorf("resolve fetch target: %w", err)
211		}
212	
213		// Fetch to a temp ref
214		tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
215		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
216		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
217	
218		if output, err := remote.Fetch(ctx, remote.FetchOptions{
219			Remote:    fetchTarget,
220			RefSpecs:  []string{refSpec},
221			NoTags:    true,
222			ExtraArgs: []string{"--no-write-fetch-head"},
223		}); err != nil {
224			return fmt.Errorf("fetch failed: %s", output)
225		}
226	
227		repo, err := OpenRepository(ctx)
228		if err != nil {
229			return fmt.Errorf("failed to open repository: %w", err)
230		}
231		defer func() {
232			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
233		}()
234	
235		// Check for rotation conflict on /full/current
236		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
237			remoteOnlyArchives, detectErr := detectRemoteOnlyArchives(ctx, target, repo)
238			if detectErr == nil && len(remoteOnlyArchives) > 0 {
239				return handleRotationConflict(ctx, target, fetchTarget, repo, refName, tmpRefName, remoteOnlyArchives)
240			}
241		}
242	
243		// Standard tree merge (no rotation detected)
244		localRef, err := repo.Reference(refName, true)
245		if err != nil {
246			return fmt.Errorf("failed to get local ref: %w", err)
247		}
248		localCommit, err := repo.CommitObject(localRef.Hash())
249		if err != nil {
250			return fmt.Errorf("failed to get local commit: %w", err)
251		}
252		localTree, err := localCommit.Tree()
253		if err != nil {
254			return fmt.Errorf("failed to get local tree: %w", err)
255		}
256	
257		remoteRef, err := repo.Reference(tmpRefName, true)
258		if err != nil {
259			return fmt.Errorf("failed to get remote ref: %w", err)
260		}
261		remoteCommit, err := repo.CommitObject(remoteRef.Hash())
262		if err != nil {
263			return fmt.Errorf("failed to get remote commit: %w", err)
264		}
265		remoteTree, err := remoteCommit.Tree()
266		if err != nil {
267			return fmt.Errorf("failed to get remote tree: %w", err)
268		}
269	
270		entries := make(map[string]object.TreeEntry)
271		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
272			return fmt.Errorf("failed to flatten local tree: %w", err)
273		}
274		if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
275			return fmt.Errorf("failed to flatten remote tree: %w", err)
276		}
277	
278		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
279		if err != nil {
280			return fmt.Errorf("failed to build merged tree: %w", err)
281		}
282	
283		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
284			[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
285			"Merge remote "+shortRefName(refName))
286		if err != nil {
287			return fmt.Errorf("failed to create merge commit: %w", err)
288		}
289	
290		newRef := plumbing.NewHashReference(refName, mergeCommitHash)
291		if err := repo.Storer.SetReference(newRef); err != nil {
292			return fmt.Errorf("failed to update ref: %w", err)
293		}
294	
295		return nil
296	}
