335	// handleRotationConflict handles the case where remote /full/current was rotated.
336	// Merges local /full/current into the latest remote archived generation to avoid
337	// duplicating checkpoint data, then adopts remote's /full/current as local.
338	func handleRotationConflict(ctx context.Context, target, fetchTarget string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
339		// Use the latest remote-only archive
340		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
341		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
342	
343		// Fetch the latest archived generation
344		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
345		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
346		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
347			Remote:    fetchTarget,
348			RefSpecs:  []string{archiveRefSpec},
349			NoTags:    true,
350			ExtraArgs: []string{"--no-write-fetch-head"},
351		}); fetchErr != nil {
352			return fmt.Errorf("fetch archived generation failed: %s", output)
353		}
354		defer func() {
355			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
356		}()
357	
358		// Get archived generation state
359		archiveRef, err := repo.Reference(archiveTmpRef, true)
360		if err != nil {
361			return fmt.Errorf("failed to get archived ref: %w", err)
362		}
363		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
364		if err != nil {
365			return fmt.Errorf("failed to get archive commit: %w", err)
366		}
367		archiveTree, err := archiveCommit.Tree()
368		if err != nil {
369			return fmt.Errorf("failed to get archive tree: %w", err)
370		}
371	
372		// Get local /full/current state
373		localRef, err := repo.Reference(refName, true)
374		if err != nil {
375			return fmt.Errorf("failed to get local ref: %w", err)
376		}
377		localCommit, err := repo.CommitObject(localRef.Hash())
378		if err != nil {
379			return fmt.Errorf("failed to get local commit: %w", err)
380		}
381		localTree, err := localCommit.Tree()
382		if err != nil {
383			return fmt.Errorf("failed to get local tree: %w", err)
384		}
385	
386		// Tree-merge local /full/current into archived generation.
387		// Git content-addressing deduplicates shared shard paths automatically.
388		entries := make(map[string]object.TreeEntry)
389		if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
390			return fmt.Errorf("failed to flatten archive tree: %w", err)
391		}
392		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
393			return fmt.Errorf("failed to flatten local tree: %w", err)
394		}
395	
396		// Update generation.json timestamps if present in the merged tree.
397		// Use the local /full/current HEAD commit time as the newest checkpoint time
398		// (more accurate than time.Now() for cleanup scheduling).
399		if genEntry, exists := entries[paths.GenerationFileName]; exists {
400			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
401				entries[paths.GenerationFileName] = updatedEntry
402			} else {
403				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
404					slog.String("error", updateErr.Error()),
405				)
406			}
407		}
408	
409		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
410		if err != nil {
411			return fmt.Errorf("failed to build merged tree: %w", err)
412		}
413	
414		// Create commit parented on archive's commit (fast-forward)
415		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
416			[]plumbing.Hash{archiveRef.Hash()},
417			"Merge local checkpoints into archived generation")
418		if err != nil {
419			return fmt.Errorf("failed to create merge commit: %w", err)
420		}
421	
422		// Update local archived ref and push it
423		newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
424		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
425			return fmt.Errorf("failed to update archive ref: %w", err)
426		}
427	
428		if _, pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
429			return fmt.Errorf("failed to push updated archive: %w", pushErr)
430		}
431	
432		// Adopt remote's /full/current as local
433		remoteRef, err := repo.Reference(tmpRefName, true)
434		if err != nil {
435			return fmt.Errorf("failed to get fetched /full/current: %w", err)
436		}
437		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
438		if err := repo.Storer.SetReference(adoptedRef); err != nil {
439			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
440		}
441	
442		return nil
443	}
