445	// updateGenerationTimestamps reads generation.json from a blob, updates
446	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
447	// an updated tree entry. Uses the local commit timestamp rather than
448	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
449	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
450		blob, err := repo.BlobObject(genBlobHash)
451		if err != nil {
452			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
453		}
454		reader, err := blob.Reader()
455		if err != nil {
456			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
457		}
458		defer reader.Close()
459	
460		data, err := io.ReadAll(reader)
461		if err != nil {
462			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
463		}
464	
465		var gen checkpoint.GenerationMetadata
466		if err := json.Unmarshal(data, &gen); err != nil {
467			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
468		}
469	
470		if newestFromLocal.After(gen.NewestCheckpointAt) {
471			gen.NewestCheckpointAt = newestFromLocal
472		}
473	
474		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
475		if err != nil {
476			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
477		}
478	
479		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
480		if err != nil {
481			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
482		}
483	
484		return object.TreeEntry{
485			Name: paths.GenerationFileName,
486			Mode: filemode.Regular,
487			Hash: newBlobHash,
488		}, nil
489	}
